import pytest
from exceptions import ContainerSkillError, RuntimeNotFoundError, ContainerExecutionError, ResourceConstraintError

def test_container_skill_error():
    # Test initialization with message
    error = ContainerSkillError("Test message")
    assert str(error) == "Test message"
    assert error.original_exception is None

    # Test initialization with message and original exception
    original_exception = ValueError("Original exception")
    error = ContainerSkillError("Test message", original_exception)
    assert str(error) == "Test message"
    assert error.original_exception == original_exception

def test_runtime_not_found_error():
    # Test initialization
    error = RuntimeNotFoundError()
    assert str(error) == ""

    # Test inheritance
    assert isinstance(error, ContainerSkillError)

def test_container_execution_error():
    # Test initialization
    error = ContainerExecutionError()
    assert str(error) == ""

    # Test inheritance
    assert isinstance(error, ContainerSkillError)

def test_resource_constraint_error():
    # Test initialization
    error = ResourceConstraintError()
    assert str(error) == ""

    # Test inheritance
    assert isinstance(error, ContainerSkillError)

def test_exception_hierarchy():
    # Test exception hierarchy
    error = ContainerSkillError("Test message")
    assert isinstance(error, Exception)

    error = RuntimeNotFoundError()
    assert isinstance(error, ContainerSkillError)
    assert isinstance(error, Exception)

    error = ContainerExecutionError()
    assert isinstance(error, ContainerSkillError)
    assert isinstance(error, Exception)

    error = ResourceConstraintError()
    assert isinstance(error, ContainerSkillError)
    assert isinstance(error, Exception)